python:
FAIL_LIMIT, PASS_LIMIT = 2, 3
results = [200, 200, 503, 503, 503, 200, 200, 200]   # Web 2's /health, every 5 s
in_service, fails, passes = True, 0, 0
for i, code in enumerate(results):
    if code == 200:
        passes, fails = passes + 1, 0
        if not in_service and passes >= PASS_LIMIT:
            in_service = True
    else:
        fails, passes = fails + 1, 0
        if in_service and fails >= FAIL_LIMIT:
            in_service = False
    print(f"t={i * 5:>2}s {code} ->", "in service" if in_service else "OUT")
